package week1.day3;

public class PrintStar {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		// print 3*3 *
		for (int i = 1; i <= 3; i++) {
			for (int j = 1; j <= 3; j++) {
				System.out.println("* ");
			}
			System.out.println();

		}

	}

}
